{#- Code generated by authfly/codegen from specs/widgets/account.def.ts. DO NOT EDIT.
    Authfly account on UI8Kit 3 primitives: profile, verified badge, sign-in methods, sign out. Props as xgen. -#}
{%- import 'authfly/components.html.j2' as af -%}
{%- set id = p.id or '' -%}{%- set l = p.labels or {} -%}{%- set error = p.error or '' -%}
{%- set formError = id ~ '-error' if error else none -%}
{%- set c11 -%}
{{ af.head(id, p.title or '', p.text or '') }}
{%- set c4 -%}{%- set c1 -%}{{ af.box('dt', af_text('muted'), {}, af_esc(l.name or '')) }}{{ af.box('dd', 'm-0 font-semibold text-foreground', {'data-testid': 'profile-name'}, af_esc(p.name or '')) }}{%- endset -%}{{ af.box('', 'grid gap-2', {}, c1) }}{%- set c3 -%}{{ af.box('dt', af_text('muted'), {}, af_esc(l.email or '')) }}{%- set c2 -%}{{ p.email or '' }}{{ af.badge('default' if p.verified or false else 'secondary', 'verified', l.verified or '' if p.verified or false else l.unverified or '') }}{%- endset -%}{{ af.box('dd', 'm-0 flex flex-wrap items-center gap-2 font-semibold text-foreground', {'data-testid': 'profile-email'}, c2) }}{%- endset -%}{{ af.box('', 'grid gap-2', {}, c3) }}{%- endset -%}{{ af.box('dl', 'm-0 grid gap-4', {'data-testid': 'profile'}, c4) }}
{{ af.prim('ui/separator/separator.html.j2', {'Decorative': true, 'Class': 'w-full border-border'}) }}
{%- set c8 -%}{{ af.title(2, id ~ '-methods', '', l.security or '') }}
{%- set c7 -%}{%- for m in p.methods or [] -%}
{%- set c6 -%}{%- set c5 -%}{{ af.icon(m.icon or '' if m.icon or '' else 'shield') }}{{ m.title or '' }}{%- endset -%}{{ af.text('span', 'flex items-center gap-2', {}, c5) }}{{ af.badge('outline', '', m.text or '') }}{%- endset -%}{{ af.box('li', 'flex items-center justify-between gap-4 text-sm text-foreground', {'data-method': m.id or none}, c6) }}
{%- endfor -%}{%- endset -%}{{ af.box('ul', 'm-0 flex list-none flex-col gap-2 p-0', {'aria-labelledby': (id) ~ '-methods' or none, 'data-testid': 'methods'}, c7) }}{%- endset -%}{{ af.stack('2', '', '', '', {}, c8) }}
{%- set c10 -%}{{ af.hidden('csrf', p.csrf or '') }}
{%- set c9 -%}{{ af.icon('log-out') }}{{ l.signout or '' }}{%- endset -%}
{{ af.button('', 'submit', af_skin('button', 'outline', 'w-full'), {'data-testid': 'signout'}, c9) }}{%- endset -%}
{{ af.form(p.signoutUrl or '', '', {'data-testid': 'signout-form'}, c10) }}
{%- endset -%}
{{ af.card(af_skin('widgetCard', 'max-w-lg'), {'data-testid': 'authfly-account', 'aria-labelledby': none if p.landmarkLabel else id ~ '-title', 'aria-label': p.landmarkLabel or none}, c11) }}
